/* ---- Bridge In-Memory Key Stores ---- */
var bridgeApiKeys = new Map();
var bridgeKeyPairs = new Map();
var bridgeTaskStore = new Map();
var bridgeNodeCrypto = require("crypto");

function generateBridgePKey() {
  return "pk_" + bridgeNodeCrypto.randomBytes(24).toString("hex");
}

/* ---- Bridge Auth Middleware ---- */
function verifyBridgeAuth(req, res, next) {
  var auth = req.headers.authorization || "";
  if (!auth.startsWith("Bearer ")) {
    return res.status(401).json({ error: "Missing or invalid Authorization header" });
  }
  var token = auth.slice(7);
  var keyData = bridgeApiKeys.get(token);
  if (!keyData) {
    return res.status(403).json({ error: "Invalid API key" });
  }
  var keyPair = bridgeKeyPairs.get(token);
  if (keyPair && keyPair.dualKeyAuth) {
    var signature = req.headers["x-bridge-signature"] || "";
    if (!signature) {
      req.bridgeDualKeyAuth = false;
    } else {
      var bodyStr = JSON.stringify(req.body || {});
      var expected = bridgeNodeCrypto.createHmac("sha256", keyPair.aKey).update(bodyStr).digest("hex");
      req.bridgeDualKeyAuth = (signature === expected);
    }
    req.bridgeScopeId = keyPair.scopeId || keyData.scopeId || "";
  } else {
    req.bridgeDualKeyAuth = false;
    req.bridgeScopeId = keyData.scopeId || "";
  }
  req.bridgeKey = keyData;
  req.bridgeStoreName = keyData.storeName || "";
  req.bridgeMarketplace = keyData.marketplace || "";
  req.bridgeAccountId = keyData.accountId || null;
  req.bridgeProfileId = keyData.profileId || null;
  next();
}

function enforceBridgeScopeBinding(req, res) {
  var rs = (req.body && req.body.storeName) || (req.query && req.query.storeName);
  var rm = (req.body && req.body.marketplace) || (req.query && req.query.marketplace);
  if (rs && rs.toLowerCase() !== req.bridgeStoreName.toLowerCase()) {
    res.status(403).json({ error: "Scope violation: key bound to store [" + req.bridgeStoreName + "], cannot access [" + rs + "]" });
    return false;
  }
  if (rm && rm.toLowerCase() !== req.bridgeMarketplace.toLowerCase()) {
    res.status(403).json({ error: "Scope violation: key bound to marketplace [" + req.bridgeMarketplace + "], cannot access [" + rm + "]" });
    return false;
  }
  return true;
}

