/**
 * Create SP Ad Groups via Amazon Ads API
 * POST /sp/adGroups with Content-Type: application/vnd.spAdGroup.v3+json
 * @param {Object} apiClient - The AmazonAdsApiClient instance (svc.client)
 * @param {Array} adGroups - Array of { campaignId, name, defaultBid, state }
 * @returns {Object} { success: Array, errors: Array }
 */
async function createSpAdGroups(apiClient, adGroups) {
  var results = { success: [], errors: [] };
  var batchSize = 100;
  var batches = Math.ceil(adGroups.length / batchSize);
  
  console.log("[Bridge] createSpAdGroups: total=" + adGroups.length + ", batches=" + batches);
  
  for (var b = 0; b < batches; b++) {
    var batch = adGroups.slice(b * batchSize, (b + 1) * batchSize);
    var payload = {
      adGroups: batch.map(function(ag) {
        return {
          campaignId: String(ag.campaignId),
          name: ag.name || "Default Ad Group",
          defaultBid: ag.defaultBid || 0.75,
          state: (ag.state || "ENABLED").toUpperCase()
        };
      })
    };
    
    try {
      var resp = await apiClient.axiosInstance.post("/sp/adGroups", payload, {
        headers: {
          "Content-Type": "application/vnd.spAdGroup.v3+json",
          "Accept": "application/vnd.spAdGroup.v3+json"
        }
      });
      
      var data = resp.data;
      // Amazon API v3 returns { adGroups: { success: [...], error: [...] } }
      if (data && data.adGroups) {
        if (data.adGroups.success) {
          for (var s of data.adGroups.success) {
            results.success.push({
              adGroupId: s.adGroupId || s.adGroup?.adGroupId,
              campaignId: s.campaignId || s.adGroup?.campaignId,
              name: s.name || s.adGroup?.name,
              index: s.index
            });
          }
        }
        if (data.adGroups.error) {
          for (var e of data.adGroups.error) {
            results.errors.push({
              index: e.index,
              code: e.code,
              details: e.description || e.details || JSON.stringify(e)
            });
          }
        }
      } else if (Array.isArray(data)) {
        // Older API format: returns array directly
        for (var item of data) {
          if (item.adGroupId) {
            results.success.push(item);
          } else if (item.code || item.error) {
            results.errors.push(item);
          }
        }
      }
    } catch (err) {
      console.error("[Bridge] createSpAdGroups batch " + (b+1) + " error:", err.message);
      for (var i = 0; i < batch.length; i++) {
        results.errors.push({
          index: b * batchSize + i,
          code: "API_ERROR",
          details: err.message
        });
      }
    }
  }
  
  console.log("[Bridge] createSpAdGroups result: success=" + results.success.length + ", errors=" + results.errors.length);
  return results;
}

/**
 * Create SP Product Ads via Amazon Ads API
 * POST /sp/productAds with Content-Type: application/vnd.spProductAd.v3+json
 * @param {Object} apiClient - The AmazonAdsApiClient instance (svc.client)
 * @param {Array} productAds - Array of { campaignId, adGroupId, asin, sku, state }
 * @returns {Object} { success: Array, errors: Array }
 */
async function createSpProductAds(apiClient, productAds) {
  var results = { success: [], errors: [] };
  var batchSize = 100;
  var batches = Math.ceil(productAds.length / batchSize);
  
  console.log("[Bridge] createSpProductAds: total=" + productAds.length + ", batches=" + batches);
  
  for (var b = 0; b < batches; b++) {
    var batch = productAds.slice(b * batchSize, (b + 1) * batchSize);
    var payload = {
      productAds: batch.map(function(pa) {
        var ad = {
          campaignId: String(pa.campaignId),
          adGroupId: String(pa.adGroupId),
          state: (pa.state || "ENABLED").toUpperCase()
        };
        if (pa.asin) ad.asin = pa.asin;
        if (pa.sku) ad.sku = pa.sku;
        return ad;
      })
    };
    
    try {
      var resp = await apiClient.axiosInstance.post("/sp/productAds", payload, {
        headers: {
          "Content-Type": "application/vnd.spProductAd.v3+json",
          "Accept": "application/vnd.spProductAd.v3+json"
        }
      });
      
      var data = resp.data;
      if (data && data.productAds) {
        if (data.productAds.success) {
          for (var s of data.productAds.success) {
            results.success.push({
              adId: s.adId || s.productAd?.adId,
              adGroupId: s.adGroupId || s.productAd?.adGroupId,
              campaignId: s.campaignId || s.productAd?.campaignId,
              asin: s.asin || s.productAd?.asin,
              index: s.index
            });
          }
        }
        if (data.productAds.error) {
          for (var e of data.productAds.error) {
            results.errors.push({
              index: e.index,
              code: e.code,
              details: e.description || e.details || JSON.stringify(e)
            });
          }
        }
      } else if (Array.isArray(data)) {
        for (var item of data) {
          if (item.adId) {
            results.success.push(item);
          } else if (item.code || item.error) {
            results.errors.push(item);
          }
        }
      }
    } catch (err) {
      console.error("[Bridge] createSpProductAds batch " + (b+1) + " error:", err.message);
      for (var i = 0; i < batch.length; i++) {
        results.errors.push({
          index: b * batchSize + i,
          code: "API_ERROR",
          details: err.message
        });
      }
    }
  }
  
  console.log("[Bridge] createSpProductAds result: success=" + results.success.length + ", errors=" + results.errors.length);
  return results;
}


